{"tool": "write_file", "args": {"path": "scripts/resend_failed_sms.py", "content": """"LIFE-209: re-send SMS messages that failed during cycle 1.

Reads data/sms_status.json to find failed vs delivered messages, fetches the
original message details from data/outbox/sms.jsonl, re-sends each failed
message via the existing send function in notifications/sms.py, and appends
audit entries to data/audit.jsonl.
"""
import json
import os
import sys

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, BASE)

STATUS_PATH = os.path.join(BASE, "data", "sms_status.json")
OUTBOX_PATH = os.path.join(BASE, "data", "outbox", "sms.jsonl")
AUDIT_PATH = os.path.join(BASE, "data", "audit.jsonl")

FAILED_STATUSES = {"failed", "error", "undelivered", "failure"}
DELIVERED_STATUSES = {"delivered", "sent", "ok", "success"}


def load_status_records():
    with open(STATUS_PATH) as f:
        data = json.load(f)
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("messages", "statuses", "records", "items"):
            if isinstance(data.get(key), list):
                return data[key]
        records = []
        for k, v in data.items():
            if isinstance(v, dict):
                rec = dict(v)
                rec.setdefault("id", k)
            else:
                rec = {"id": k, "status": v}
            records.append(rec)
        return records
    raise ValueError("Unrecognized sms_status.json format")


def rec_id(r):
    for key in ("id", "message_id", "msg_id", "sms_id"):
        if key in r and r[key] is not None:
            return r[key]
    return None


def rec_status(r):
    for key in ("status", "state", "result", "delivery_status"):
        if key in r and r[key] is not None:
            return str(r[key]).strip().lower()
    return ""


def main():
    records = load_status_records()
    failed_ids = set()
    delivered_ids = set()
    for r in records:
        rid = rec_id(r)
        st = rec_status(r)
        if st in FAILED_STATUSES:
            failed_ids.add(rid)
        elif st in DELIVERED_STATUSES:
            delivered_ids.add(rid)

    # Load original messages from the outbox (JSONL).
    originals = {}
    with open(OUTBOX_PATH) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            msg = json.loads(line)
            mid = rec_id(msg)
            if mid in failed_ids and mid not in originals:
                originals[mid] = msg

    # Reuse the existing send function from notifications/sms.py.
    import notifications.sms as sms_mod
    send_fn = None
    for name in ("send_sms", "send", "send_text", "send_message", "send_text_message"):
        fn = getattr(sms_mod, name, None)
        if callable(fn):
            send_fn = fn
            break
    if send_fn is None:
        for name in dir(sms_mod):
            if "send" in name.lower() and callable(getattr(sms_mod, name)):
                send_fn = getattr(sms_mod, name)
                break
    if send_fn is None:
        raise RuntimeError("No send function found in notifications/sms.py")

    def do_send(household, message, details):
        try:
            return send_fn(household=household, message=message, details=details)
        except TypeError:
            pass
        try:
            return send_fn(household, message, details)
        except TypeError:
            pass
        try:
            return send_fn(household, message)
        except TypeError:
            return send_fn(household, message=message)

    sent = []
    for mid in sorted(failed_ids, key=str):
        if mid not in originals:
            print("WARNING: no original message found for failed id %r" % (mid,))
            continue
        msg = originals[mid]
        household = None
        for key in ("household", "household_id", "recipient", "to"):
            if key in msg:
                household = msg[key]
                break
        message = None
        for key in ("message", "text", "body", "content"):
            if key in msg:
                message = msg[key]
                break
        details = msg.get("details")
        do_send(household, message, details)
        sent.append({"message_id": mid, "household": household, "message": message, "details": details})

    # Append audit entries consistent with the existing audit log.
    existing_keys = set()
    if os.path.exists(AUDIT_PATH):
        with open(AUDIT_PATH) as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        existing_keys.update(json.loads(line).keys())
                    except Exception:
                        pass
    with open(AUDIT_PATH, "a") as f:
        for s in sent:
            entry = {}
            if "action" in existing_keys or not existing_keys:
                entry["action"] = "resend_failed_sms"
            if "event" in existing_keys:
                entry["event"] = "resend_failed_sms"
            if "type" in existing_keys:
                entry["type"] = "sms_resend"
            if "message_id" in existing_keys or "id" in existing_keys:
                entry["message_id"] = s["message_id"]
            if "household" in existing_keys or "household_id" in existing_keys:
                entry["household"] = s["household"]
            if "message" in existing_keys or "text" in existing_keys:
                entry["message"] = s["message"]
            if "details" in existing_keys:
                entry["details"] = s["details"]
            if "status" in existing_keys:
                entry["status"] = "resent"
            if not entry:
                entry = {"action": "resend_failed_sms", "message_id": s["message_id"], "household": s["household"]}
            f.write(json.dumps(entry) + "\n")

    print("Resent %d failed message(s):" % len(sent))
    for s in sent:
        print("  - id=%r household=%r" % (s["message_id"], s["household"]))
    print("Delivered households skipped: %d" % len(delivered_ids))


if __name__ == "__main__":
    main()
